   {
      const std::vector<char> buffer{Data, Data + Size};

      static constexpr glz::opts opts{.null_terminated = false};
      glz::json_t json{};
      auto ec = glz::read<opts>(json, buffer);
      if (!ec) {
         [[maybe_unused]] auto s = json.size();
