   {
      const auto& input = buffer;
      glz::json_t json{};
      auto ec = glz::read_json(json, input);
      if (!ec) {
         [[maybe_unused]] auto s = json.size();
      }
   }

   // non-const input buffer
   {
      glz::json_t json{};
      auto ec = glz::read_json(json, buffer);
      if (!ec) {
         [[maybe_unused]] auto s = json.size();
      }
   }

   return 0;
}
